<?php
declare(strict_types=1);
require __DIR__.'/purchases_fixture.php';
$vendor=$svc->saveSupplier($a,12,null,null,['name'=>'=Synthetic vendor','tax_id'=>'11222333000181','email'=>'supplier@example.invalid','phone'=>'','address'=>''], $key('portal-vendor'));
$request=$svc->createRequest($a,12,['title'=>'Private RFQ A','needed_date'=>$today,'currency'=>'BRL','lines'=>[['description'=>'Portal item','unit'=>'UN','quantity'=>'1.000']]],$key('portal-request'));
$other=$svc->createRequest($a,12,['title'=>'Other private RFQ A','needed_date'=>$today,'currency'=>'BRL','lines'=>[['description'=>'Other item','unit'=>'UN','quantity'=>'1.000']]],$key('other-request'));
$invite=$svc->issueInvite($a,12,$request,$vendor,2,$key('portal-invite'));
purchaseCheck(is_string($invite['secret'])&&$invite['replayed']===false,'invitation secret returned once');
$retry=$svc->issueInvite($a,12,$request,$vendor,2,$key('portal-invite')); purchaseCheck($retry['secret']===null&&$retry['replayed']===true,'invitation replay never reconstructs secret');
$saved=$db->query('SELECT * FROM '.$p.'company_purchase_invites WHERE id=?',[$invite['id']])->row_array();
purchaseCheck($saved['secret_hash']===hash('sha256',$invite['secret'])&&!str_contains(json_encode(purchaseSnapshot()),$invite['secret']),'raw invitation absent from tables/audit/receipts');
[$portal,$who]=CompanyPurchases::forPortal($db,$p,$invite['secret']); $view=$portal->portalView();
purchaseCheck((int)$view['request']['id']===$request&&$view['supplier']['id']===$vendor,'portal identity binds request and supplier from persistence');
$identity=$portal->portalIdentity(str_repeat('S',32)); purchaseCheck(!isset($identity['secret']),'portal session contains signed hash identity, not raw invitation');
[$sessionPortal]=CompanyPurchases::forPortalSession($db,$p,$identity,str_repeat('S',32)); purchaseCheck($sessionPortal->portalView()['request']['id']===$view['request']['id'],'signed session resumes bound supplier');
$forged=$identity; $forged['issuer_id']=$b; purchaseThrows(fn()=>CompanyPurchases::forPortalSession($db,$p,$forged,str_repeat('S',32)),'company_purchase_portal_denied','session issuer forgery denied');
purchaseThrows(fn()=>$portal->page($a,12,'request'),'company_purchase_portal_denied','portal cannot use internal generic listing');
purchaseThrows(fn()=>$portal->get($a,12,'request',$other),'company_purchase_portal_denied','portal cannot use internal detail even in same company');
$quoteInput=['request_id'=>$request,'supplier_id'=>$vendor,'valid_until'=>$today,'unit_prices'=>['10.00'],'tax_rate'=>'0.00','note'=>'Supplier quote'];
$quote=$portal->quote($a,12,$quoteInput,$key('portal-quote')); purchaseCheck($svc->get($a,12,'quote',$quote)['origin']==='supplier_portal'&&(int)$svc->get($a,12,'quote',$quote)['created_by']===0,'supplier quote has explicit portal origin and does not impersonate staff');
purchaseThrows(fn()=>$portal->quote($a,12,array_replace($quoteInput,['request_id'=>$other]),$key('cross-request-quote')),'company_purchase_denied','portal cannot quote another RFQ');
purchaseThrows(fn()=>$portal->createRequest($a,12,['title'=>'unauthorized','needed_date'=>$today,'currency'=>'BRL','lines'=>[['description'=>'bad','unit'=>'UN','quantity'=>'1.000']]],$key('portal-create')),'company_purchase_portal_denied','portal cannot create internal procurement requests');
$pdf="%PDF-1.4\n1 0 obj\n<< /Type /Catalog >>\nendobj\ntrailer\n<< /Root 1 0 R >>\n%%EOF\n";
$private=$svc->upload($a,12,$request,$vendor,'private.pdf',$pdf,false,$key('private-file'));
$shared=$svc->upload($a,12,$request,null,'rfq.pdf',$pdf,true,$key('shared-file'));
$supplierFile=$portal->upload($a,12,$request,$vendor,'supplier.pdf',$pdf,true,$key('supplier-file'));
purchaseCheck(count($portal->files($a,12,$request))===2&&count($svc->files($a,12,$request))===3,'supplier sees only explicitly published and own files');
purchaseCheck($portal->download($a,12,$shared)['content']===$pdf,'authorized supplier downloads exact private stored bytes');
purchaseThrows(fn()=>$portal->download($a,12,$private),'company_purchase_denied','unpublished file is denied');
purchaseThrows(fn()=>$svc->download($b,12,$shared),'company_purchase_denied','other company cannot download file by ID');
purchaseThrows(fn()=>$svc->upload($a,12,$request,null,'../escape.pdf',$pdf,false,$key('bad-file')),'company_operation_file_invalid','unsafe attachment name rejected');
$svc->approveRequest($a,12,$request,1,$key('portal-approve'));
$order=$svc->createOrder($a,12,['quote_id'=>$quote,'request_revision'=>2,'order_date'=>$today,'expected_date'=>$today],$key('portal-order'));
$bytes=$portal->orderPdf($a,12,$order); purchaseCheck(str_starts_with($bytes,'%PDF-')&&strlen($bytes)>1000,'supplier order PDF renders actual snapshotted purchase');
$receipt=$svc->receive($a,12,$order,1,['received_date'=>$today,'lines'=>[['line'=>1,'quantity'=>'1.000']]],$key('portal-receipt'));
$payable=$svc->postDocument($a,12,['order_id'=>$order,'receipt_ids'=>[$receipt],'vendor_number'=>'=External-100','document_date'=>$today,'due_date'=>$today,'category_id'=>$categories[$a],'file_id'=>$supplierFile],$key('portal-document'));
purchaseCheck(count($portal->portalView()['documents'])===1&&$portal->portalView()['documents'][0]['outstanding_cents']===1000,'portal displays only own posted obligation without bank confirmation');
$fileRow=$svc->get($a,12,'file',$supplierFile); purchaseThrows(fn()=>$svc->hideFile($a,12,$supplierFile,(int)$fileRow['revision'],$key('hide-evidence')),'company_purchase_evidence_immutable','linked invoice evidence cannot be hidden');
$ap=$svc->get($a,12,'payable',$payable); $expense=$expenseService->get($a,12,(int)$ap['expense_id']);
purchaseThrows(fn()=>$expenseService->change($a,12,(int)$ap['expense_id'],$expense['revision_token'],$key('cancel-purchase-expense')),'company_expense_purchase_source_immutable','canonical expense cancel is fenced by Purchase origin');
$update=['category_id'=>$categories[$a],'currency'=>'BRL','date'=>$today,'description'=>'wrong','amount'=>'11.00','tax_rate'=>'0.00'];
purchaseThrows(fn()=>$expenseService->change($a,12,(int)$ap['expense_id'],$expense['revision_token'],$key('edit-purchase-expense'),$update),'company_expense_purchase_source_immutable','canonical expense edit cannot diverge AP');
$report=$svc->report($a,12,'2000-01-01',$today); purchaseCheck($report['totals_for_this_page']['BRL']['amount_cents']===1000&&$report['totals_for_this_page']['BRL']['outstanding_cents']===1000,'AP report derives obligation from document and event source');
$csv=$svc->export($a,12,'2000-01-01',$today); purchaseCheck(str_contains($csv,"'=Synthetic vendor")&&str_contains($csv,"'=External-100")&&!str_contains($csv,'Other private'),'CSV neutralizes formula cells and contains only owned source rows');
purchaseThrows(fn()=>$svc->report($a,14,'2000-01-01',$today),'company_purchase_denied','ordinary purchase view cannot export sensitive AP report');
$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=? AND staff_id=12 AND feature='purchases' AND capability='portal'",[$a]);
purchaseThrows(fn()=>$portal->portalView(),'company_purchase_denied','live issuer owner permission revocation disables invitation');
$db->query("INSERT INTO {$p}issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(?,12,'purchases','portal')",[$a]);
$db->query('UPDATE '.$p.'company_purchase_invites SET expires_at=? WHERE id=?',['2000-01-01 00:00:00',$invite['id']]);
purchaseThrows(fn()=>$portal->portalView(),'company_purchase_portal_denied','expired invitation denied without any cron dependency');
$db->query('UPDATE '.$p.'company_purchase_invites SET expires_at=? WHERE id=?',[$saved['expires_at'],$invite['id']]);
$svc->revokeInvite($a,12,$invite['id'],1,$key('portal-revoke')); purchaseThrows(fn()=>$sessionPortal->portalView(),'company_purchase_portal_denied','revocation invalidates already signed supplier session');
echo 'Purchases portal/files/reports: '.$GLOBALS['essentialChecks'].' checks passed on real mysql'.PHP_EOL;
